import React, { useEffect, useMemo, useState } from 'react';
import { firebaseService } from '../firebase/asteriaFirebaseService.js';
import { EmptyState, Panel, StatusPill } from '../components/WorkspaceUI.jsx';

const array = value => Array.isArray(value) ? value : [];
const uid = prefix => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
const dateLabel = value => value ? new Date(value).toLocaleString() : 'Not recorded';

function SectionStatus({ message }) {
  return message ? <p className="react-action-message" role="status">{message}</p> : null;
}

function RecordActions({ onEdit, onDelete }) {
  return <div className="react-record-actions"><button type="button" onClick={onEdit}>Edit</button><button type="button" className="danger" onClick={onDelete}>Delete</button></div>;
}

export function QuestWorkspace({ campaignId, workspace, characters, saveSection }) {
  const quests=array(workspace.quests);
  const [draft,setDraft]=useState({id:'',title:'',objective:'',reward:'',status:'Draft',visibility:'Party'});
  const [recipients,setRecipients]=useState([]);
  const [message,setMessage]=useState('');
  const [busy,setBusy]=useState(false);
  const reset=()=>setDraft({id:'',title:'',objective:'',reward:'',status:'Draft',visibility:'Party'});
  const save=async()=>{
    if(!draft.title.trim())return setMessage('Enter a quest title.');
    const record={...draft,id:draft.id||uid('quest'),title:draft.title.trim(),updatedAt:new Date().toISOString()};
    const next=draft.id?quests.map(item=>item.id===draft.id?record:item):[record,...quests];
    setBusy(true);const result=await saveSection('quests',next);setBusy(false);
    setMessage(result?.ok?'Quest saved to the live campaign workspace.':result?.error||'Quest could not be saved.');
    if(result?.ok)reset();
  };
  const assign=async quest=>{
    if(!recipients.length)return setMessage('Select at least one player character.');
    setBusy(true);const result=await firebaseService.assignQuest(campaignId,quest,recipients);setBusy(false);
    setMessage(result?.ok?`${quest.title} sent to ${recipients.length} character${recipients.length===1?'':'s'}.`:result?.error||'Quest could not be assigned.');
  };
  return <div className="react-gm-workspace-grid quests">
    <Panel title="Quest Builder" eyebrow="Campaign Objectives">
      <div className="react-form-grid"><label>Quest Title<input value={draft.title} onChange={event=>setDraft(value=>({...value,title:event.target.value}))}/></label><label>Status<select value={draft.status} onChange={event=>setDraft(value=>({...value,status:event.target.value}))}>{['Draft','Active','Completed','Failed','Archived'].map(value=><option key={value}>{value}</option>)}</select></label><label>Visibility<select value={draft.visibility} onChange={event=>setDraft(value=>({...value,visibility:event.target.value}))}><option>Party</option><option>GM Only</option></select></label></div>
      <label>Objective<textarea rows="5" value={draft.objective} onChange={event=>setDraft(value=>({...value,objective:event.target.value}))}/></label>
      <label>Rewards<textarea rows="3" value={draft.reward} onChange={event=>setDraft(value=>({...value,reward:event.target.value}))}/></label>
      <div className="react-action-row"><button className="primary" disabled={busy} onClick={save}>{draft.id?'Update Quest':'Create Quest'}</button>{draft.id?<button onClick={reset}>Cancel Edit</button>:null}</div><SectionStatus message={message}/>
    </Panel>
    <Panel title="Quest Ledger" eyebrow="Live Quest Control" action={<StatusPill>{quests.length} quests</StatusPill>}>
      <div className="react-recipient-actions"><button onClick={()=>setRecipients(Object.keys(characters))}>Select All Players</button><button onClick={()=>setRecipients([])}>Clear</button><span>{recipients.length} recipients</span></div>
      <div className="react-recipient-grid">{Object.values(characters).map(character=><label key={character.id}><input type="checkbox" checked={recipients.includes(character.id)} onChange={event=>setRecipients(ids=>event.target.checked?[...new Set([...ids,character.id])]:ids.filter(id=>id!==character.id))}/>{character.name}</label>)}</div>
      <div className="react-record-list">{quests.map(quest=><article key={quest.id}><div className="react-record-heading"><div><StatusPill tone={quest.status==='Active'?'success':''}>{quest.status}</StatusPill><h3>{quest.title}</h3></div><small>{quest.visibility}</small></div><p>{quest.objective||'No objective recorded.'}</p>{quest.reward?<small><b>Reward:</b> {quest.reward}</small>:null}<div className="react-action-row"><button className="primary" disabled={busy||quest.visibility==='GM Only'} onClick={()=>assign(quest)}>Send to Selected Players</button><RecordActions onEdit={()=>setDraft({...quest})} onDelete={()=>saveSection('quests',quests.filter(item=>item.id!==quest.id))}/></div></article>)}{!quests.length?<EmptyState title="No campaign quests">Create the first objective, then send it to selected character dashboards.</EmptyState>:null}</div>
    </Panel>
  </div>;
}

export function NotesWorkspace({ workspace, session, saveSection }) {
  const notes=workspace.notes||{privateNotes:'',sessionLogs:[]};
  const [privateNotes,setPrivateNotes]=useState(notes.privateNotes||'');
  const [log,setLog]=useState({title:'',body:''});
  const [message,setMessage]=useState('');
  useEffect(()=>setPrivateNotes(notes.privateNotes||''),[notes.privateNotes]);
  const saveNotes=async()=>{const result=await saveSection('notes',{...notes,privateNotes});setMessage(result?.ok?'Private GM notes synchronized.':result?.error||'Notes could not be saved.');};
  const addLog=async()=>{
    if(!log.title.trim()&&!log.body.trim())return setMessage('Add a session title or log entry.');
    const record={id:uid('session-log'),title:log.title.trim()||`Session ${session?.number||''}`.trim(),body:log.body.trim(),sessionId:session?.id||'',sessionStatus:session?.status||'idle',createdAt:new Date().toISOString()};
    const result=await saveSection('notes',{...notes,privateNotes,sessionLogs:[record,...array(notes.sessionLogs)]});
    setMessage(result?.ok?'Session log added.':result?.error||'Session log could not be saved.');if(result?.ok)setLog({title:'',body:''});
  };
  const exportLogs=()=>{
    const blob=new Blob([JSON.stringify({privateNotes,sessionLogs:notes.sessionLogs},null,2)],{type:'application/json'});
    const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`asteria-gm-session-logs-${new Date().toISOString().slice(0,10)}.json`;anchor.click();URL.revokeObjectURL(url);
  };
  return <div className="react-gm-workspace-grid notes">
    <Panel title="Private GM Notes" eyebrow="Preparation & Live Notes"><label>Campaign Notes<textarea className="react-gm-notebook" value={privateNotes} onChange={event=>setPrivateNotes(event.target.value)} placeholder="Private preparation, NPC motives, hidden outcomes, and session notes..."/></label><div className="react-action-row"><button className="primary" onClick={saveNotes}>Save Notes</button><button onClick={exportLogs}>Export Logs</button></div><SectionStatus message={message}/></Panel>
    <Panel title="Session Log" eyebrow="Campaign Record" action={<StatusPill tone={session?.status==='active'?'success':''}>{session?.status||'idle'}</StatusPill>}><div className="react-form-grid"><label>Log Title<input value={log.title} onChange={event=>setLog(value=>({...value,title:event.target.value}))} placeholder="Session summary"/></label></div><label>Entry<textarea rows="5" value={log.body} onChange={event=>setLog(value=>({...value,body:event.target.value}))}/></label><button className="primary" onClick={addLog}>Add Log Entry</button><div className="react-record-list compact">{array(notes.sessionLogs).map(record=><article key={record.id}><div className="react-record-heading"><h3>{record.title}</h3><small>{dateLabel(record.createdAt)}</small></div><p>{record.body||'No summary.'}</p><button className="danger" onClick={()=>saveSection('notes',{...notes,privateNotes,sessionLogs:array(notes.sessionLogs).filter(item=>item.id!==record.id)})}>Delete</button></article>)}{!array(notes.sessionLogs).length?<EmptyState title="No session logs"/>:null}</div></Panel>
  </div>;
}

function ShopManager({ campaignId, characters, itemEcosystem, customItems }) {
  const shops=array(itemEcosystem?.shops);
  const catalog=useMemo(()=>{const seen=new Set();return [...array(window.AsteriaInventory?.catalogEntries?.()),...array(customItems)].filter(item=>{const key=String(item.id||item.slug||item.name||item.title);if(!key||seen.has(key))return false;seen.add(key);return true;});},[customItems]);
  const [selectedId,setSelectedId]=useState(shops[0]?.id||'');
  const [draft,setDraft]=useState({name:'',type:'General Goods',buyModifier:1,sellModifier:1});
  const [search,setSearch]=useState('');const [quantity,setQuantity]=useState(1);const [message,setMessage]=useState('');
  useEffect(()=>{if(selectedId&&!shops.some(shop=>shop.id===selectedId))setSelectedId(shops[0]?.id||'');},[shops,selectedId]);
  const selected=shops.find(shop=>shop.id===selectedId)||null;
  const run=async action=>{const result=await firebaseService.manageShop(campaignId,action);setMessage(result?.ok?'Shop system synchronized.':result?.error||'Shop could not be updated.');return result;};
  const create=async()=>{if(!draft.name.trim())return setMessage('Enter a shop name.');const result=await run({type:'save',shop:{...draft,id:uid('shop'),status:'closed',visitorCharacterIds:[],stock:[],currencyCopper:100000}});if(result?.ok)setDraft({...draft,name:''});};
  const updateSelected=patch=>selected&&run({type:'save',shop:{...selected,...patch}});
  const matches=search?catalog.filter(item=>String(item.name||item.title||'').toLowerCase().includes(search.toLowerCase())).slice(0,10):[];
  return <Panel title="Campaign Shops" eyebrow="Merchant & Stock Manager" action={<StatusPill>{shops.length} shops</StatusPill>}>
    <div className="react-shop-layout"><section><h3>Create Shop</h3><div className="react-form-grid"><label>Name<input value={draft.name} onChange={event=>setDraft(value=>({...value,name:event.target.value}))}/></label><label>Type<select value={draft.type} onChange={event=>setDraft(value=>({...value,type:event.target.value}))}>{['General Goods','Blacksmith','Armourer','Alchemist','Enchanter','Magical Goods','Temple Services','Travelling Merchant'].map(value=><option key={value}>{value}</option>)}</select></label><label>Buy Modifier<input type="number" min="0.1" step="0.05" value={draft.buyModifier} onChange={event=>setDraft(value=>({...value,buyModifier:Number(event.target.value||1)}))}/></label><label>Sell Modifier<input type="number" min="0.1" step="0.05" value={draft.sellModifier} onChange={event=>setDraft(value=>({...value,sellModifier:Number(event.target.value||1)}))}/></label></div><button className="primary" onClick={create}>Create Shop</button><div className="react-shop-list">{shops.map(shop=><button className={selectedId===shop.id?'active':''} key={shop.id} onClick={()=>setSelectedId(shop.id)}><b>{shop.name}</b><small>{shop.type} | {shop.status}</small></button>)}</div></section><section>{selected?<><div className="react-record-heading"><div><h3>{selected.name}</h3><small>{array(selected.stock).length} stock lines</small></div><div className="react-record-actions"><button onClick={()=>updateSelected({status:selected.status==='open'?'closed':'open'})}>{selected.status==='open'?'Close Shop':'Open Shop'}</button><button className="danger" onClick={()=>run({type:'delete',shopId:selected.id})}>Delete</button></div></div><h4>Visiting Characters</h4><div className="react-recipient-grid">{Object.values(characters).map(character=><label key={character.id}><input type="checkbox" checked={array(selected.visitorCharacterIds).includes(character.id)} onChange={event=>updateSelected({visitorCharacterIds:event.target.checked?[...new Set([...array(selected.visitorCharacterIds),character.id])]:array(selected.visitorCharacterIds).filter(id=>id!==character.id)})}/>{character.name}</label>)}</div><div className="react-form-grid"><label>Search Item Compendium<input type="search" value={search} onChange={event=>setSearch(event.target.value)} placeholder="Add stock..."/></label><label>Quantity<input type="number" min="1" value={quantity} onChange={event=>setQuantity(Math.max(1,Number(event.target.value||1)))}/></label></div>{search?<div className="react-search-results">{matches.map(item=><button key={item.id||item.slug||item.name} onClick={()=>{run({type:'stock',shopId:selected.id,item,quantity});setSearch('');}}>{item.name||item.title}</button>)}</div>:null}<div className="react-stock-list">{array(selected.stock).map((row,index)=><article key={`${row.item?.id||row.item?.name}-${index}`}><div><b>{row.item?.name||row.item?.title||'Item'}</b><small>x{row.qty} | {Number(row.priceCopper??0).toLocaleString()} copper</small></div><button className="danger" onClick={()=>run({type:'remove-stock',shopId:selected.id,stockIndex:index})}>Remove</button></article>)}{!array(selected.stock).length?<EmptyState title="No shop stock"/>:null}</div></>:<EmptyState title="No shop selected">Create a shop to manage visitors and stock.</EmptyState>}</section></div><SectionStatus message={message}/>
  </Panel>;
}

export function EconomyWorkspace({ campaignId, workspace, characters, itemEcosystem, customItems, saveSection }) {
  const economy=workspace.economy||{};const routes=array(economy.routes);const [draft,setDraft]=useState({name:'',from:'',to:'',status:'Open'});const [message,setMessage]=useState('');
  const [controls,setControls]=useState({status:economy.status||'Stable',scarcity:economy.scarcity||'Normal',inflation:Number(economy.inflation||0),treasury:Number(economy.treasury||0)});
  useEffect(()=>setControls({status:economy.status||'Stable',scarcity:economy.scarcity||'Normal',inflation:Number(economy.inflation||0),treasury:Number(economy.treasury||0)}),[economy.status,economy.scarcity,economy.inflation,economy.treasury]);
  const update=async patch=>{const result=await saveSection('economy',{...economy,...patch});setMessage(result?.ok?'Economy controls synchronized.':result?.error||'Economy could not be saved.');};
  const addRoute=()=>{if(!draft.name.trim())return setMessage('Enter a trade route name.');update({routes:[...routes,{...draft,id:uid('route')} ]});setDraft({name:'',from:'',to:'',status:'Open'});};
  const trades=[...array(itemEcosystem?.playerItemRequests),...array(itemEcosystem?.directTrades)];
  return <div className="react-gm-workspace-grid economy"><Panel title="World Economy" eyebrow="Campaign Economy Controls"><div className="react-form-grid"><label>Economy Status<select value={controls.status} onChange={event=>setControls(value=>({...value,status:event.target.value}))}>{['Booming','Stable','Strained','Recession','Collapsed'].map(value=><option key={value}>{value}</option>)}</select></label><label>Scarcity<select value={controls.scarcity} onChange={event=>setControls(value=>({...value,scarcity:event.target.value}))}>{['Abundant','Normal','Scarce','Critical'].map(value=><option key={value}>{value}</option>)}</select></label><label>Inflation %<input type="number" value={controls.inflation} onChange={event=>setControls(value=>({...value,inflation:Number(event.target.value||0)}))}/></label><label>Treasury (copper)<input type="number" min="0" value={controls.treasury} onChange={event=>setControls(value=>({...value,treasury:Number(event.target.value||0)}))}/></label></div><button className="primary" onClick={()=>update(controls)}>Apply Economy Controls</button><h3>Trade Routes</h3><div className="react-form-grid"><label>Name<input value={draft.name} onChange={event=>setDraft(value=>({...value,name:event.target.value}))}/></label><label>From<input value={draft.from} onChange={event=>setDraft(value=>({...value,from:event.target.value}))}/></label><label>To<input value={draft.to} onChange={event=>setDraft(value=>({...value,to:event.target.value}))}/></label><label>Status<select value={draft.status} onChange={event=>setDraft(value=>({...value,status:event.target.value}))}>{['Open','Unstable','Closed','Blockaded'].map(value=><option key={value}>{value}</option>)}</select></label></div><button className="primary" onClick={addRoute}>Add Trade Route</button><div className="react-record-list compact">{routes.map(route=><article key={route.id}><div><b>{route.name}</b><small>{route.from} to {route.to} | {route.status}</small></div><button className="danger" onClick={()=>update({routes:routes.filter(item=>item.id!==route.id)})}>Remove</button></article>)}</div><SectionStatus message={message}/></Panel><ShopManager campaignId={campaignId} characters={characters} itemEcosystem={itemEcosystem} customItems={customItems}/><Panel title="Trade & Inventory Audit" eyebrow="Shared Item Activity" action={<StatusPill>{trades.length} records</StatusPill>}><div className="react-audit-table"><div className="head"><b>Type</b><b>Participants</b><b>Item</b><b>Status</b></div>{trades.slice().reverse().slice(0,50).map(record=><div key={record.id}><span>{record.mode||'Trade'}</span><span>{record.fromCharacterName||characters[record.fromCharacterId]?.name||'Player'} / {record.toCharacterName||characters[record.toCharacterId]?.name||'Player'}</span><span>{record.item?.name||'Item'}</span><StatusPill tone={record.status==='accepted'?'success':''}>{record.status||'pending'}</StatusPill></div>)}{!trades.length?<EmptyState title="No item activity"/>:null}</div></Panel></div>;
}

export function CraftingWorkspace({ workspace, characters, saveSection }) {
  const crafting=workspace.crafting||{};const [view,setView]=useState('projects');const [message,setMessage]=useState('');const [draft,setDraft]=useState({name:'',characterId:'',type:'Crafting',requirements:'',result:''});
  const save=async next=>{const result=await saveSection('crafting',next);setMessage(result?.ok?'Crafting system synchronized.':result?.error||'Crafting system could not be saved.');};
  const collections={projects:array(crafting.projects),recipes:array(crafting.recipes),enchantments:array(crafting.enchantments)};const records=collections[view];
  const create=()=>{if(!draft.name.trim())return setMessage('Enter a name.');const record={...draft,id:uid(view.slice(0,-1)),status:view==='projects'?'Pending':'Available',createdAt:new Date().toISOString()};save({...crafting,[view]:[record,...records]});setDraft({name:'',characterId:'',type:view==='enchantments'?'Enchantment':view==='recipes'?'Recipe':'Crafting',requirements:'',result:''});};
  const updateRecord=(id,patch)=>save({...crafting,[view]:records.map(record=>record.id===id?{...record,...patch}:record)});
  return <Panel title="Crafting Workshop" eyebrow="Projects, Recipes & Enchantments" action={<div className="react-segmented-actions">{['projects','recipes','enchantments'].map(id=><button className={view===id?'active':''} key={id} onClick={()=>setView(id)}>{id}</button>)}</div>}><div className="react-gm-workspace-grid crafting"><section><h3>{view==='projects'?'Submit GM Project':view==='recipes'?'Create Recipe':'Create Enchantment'}</h3><div className="react-form-grid"><label>Name<input value={draft.name} onChange={event=>setDraft(value=>({...value,name:event.target.value}))}/></label>{view==='projects'?<label>Character<select value={draft.characterId} onChange={event=>setDraft(value=>({...value,characterId:event.target.value}))}><option value="">Campaign / NPC</option>{Object.values(characters).map(character=><option value={character.id} key={character.id}>{character.name}</option>)}</select></label>:null}<label>Type<input value={draft.type} onChange={event=>setDraft(value=>({...value,type:event.target.value}))}/></label></div><label>Materials / Requirements<textarea rows="4" value={draft.requirements} onChange={event=>setDraft(value=>({...value,requirements:event.target.value}))}/></label><label>Result / Effect<textarea rows="4" value={draft.result} onChange={event=>setDraft(value=>({...value,result:event.target.value}))}/></label><button className="primary" onClick={create}>Add {view.slice(0,-1)}</button><SectionStatus message={message}/></section><section><div className="react-record-list">{records.map(record=><article key={record.id}><div className="react-record-heading"><div><StatusPill tone={record.status==='Approved'||record.status==='Completed'?'success':''}>{record.status}</StatusPill><h3>{record.name}</h3></div><small>{record.type}</small></div><p>{record.requirements||'No requirements recorded.'}</p>{record.result?<small><b>Result:</b> {record.result}</small>:null}<div className="react-action-row">{view==='projects'?<><button onClick={()=>updateRecord(record.id,{status:'Approved'})}>Approve</button><button onClick={()=>updateRecord(record.id,{status:'Completed'})}>Complete</button><button onClick={()=>updateRecord(record.id,{status:'Denied'})}>Deny</button></>:null}<button className="danger" onClick={()=>save({...crafting,[view]:records.filter(item=>item.id!==record.id)})}>Delete</button></div></article>)}{!records.length?<EmptyState title={`No ${view}`}/>:null}</div></section></div></Panel>;
}

export function CampaignManagerWorkspace({ campaignId, campaign, characters, session, workspace, saveSection }) {
  const details=workspace.campaign||{};const [draft,setDraft]=useState({name:campaign?.name||'',description:details.synopsis||campaign?.description||'',location:details.location||campaign?.location||'',playerLimit:Number(details.playerLimit||campaign?.playerLimit||6)});const [message,setMessage]=useState('');
  useEffect(()=>setDraft({name:campaign?.name||'',description:details.synopsis||campaign?.description||'',location:details.location||campaign?.location||'',playerLimit:Number(details.playerLimit||campaign?.playerLimit||6)}),[campaign?.name,campaign?.description,campaign?.location,campaign?.playerLimit,details.synopsis,details.location,details.playerLimit]);
  const save=async()=>{const [campaignResult,workspaceResult]=await Promise.all([firebaseService.updateCampaignDetails(campaignId,draft),saveSection('campaign',{...details,synopsis:draft.description,location:draft.location,playerLimit:draft.playerLimit})]);setMessage(campaignResult?.ok&&workspaceResult?.ok?'Campaign settings synchronized.':campaignResult?.error||workspaceResult?.error||'Campaign settings could not be saved.');};
  const players=Object.values(campaign?.players||{});
  return <div className="react-gm-workspace-grid campaign"><Panel title="Campaign Manager" eyebrow="Identity, Invite & Session"><div className="react-campaign-code"><span>Unique Campaign Number</span><strong>{campaign?.ucn||campaign?.uniqueCampaignCode||'Not generated'}</strong><small>Share this 12-digit UCN with players joining through Campaign Forge.</small></div><div className="react-form-grid"><label>Campaign Name<input value={draft.name} onChange={event=>setDraft(value=>({...value,name:event.target.value}))}/></label><label>Current Location<input value={draft.location} onChange={event=>setDraft(value=>({...value,location:event.target.value}))}/></label><label>Player Limit<input type="number" min="1" max="50" value={draft.playerLimit} onChange={event=>setDraft(value=>({...value,playerLimit:Number(event.target.value||6)}))}/></label></div><label>Campaign Synopsis<textarea rows="6" value={draft.description} onChange={event=>setDraft(value=>({...value,description:event.target.value}))}/></label><button className="primary" onClick={save}>Save Campaign Settings</button><SectionStatus message={message}/></Panel><Panel title="Linked Accounts & Characters" eyebrow="Campaign Membership" action={<StatusPill tone="success">{Object.keys(characters).length} characters</StatusPill>}><div className="react-membership-summary"><div><small>Session</small><b>{session?.status||'idle'}</b></div><div><small>Players</small><b>{players.filter(player=>player.role!=='gm').length}</b></div><div><small>GMs</small><b>{1+array(campaign?.gmUids).length}</b></div><div><small>Linked Characters</small><b>{Object.keys(characters).length}</b></div></div><div className="react-record-list compact">{players.map(player=><article key={player.uid}><div><b>{player.displayName||player.uid}</b><small>{player.role||'player'} | {array(player.characterIds).length} characters</small></div><StatusPill tone={player.status==='active'?'success':''}>{player.status||'active'}</StatusPill></article>)}{!players.length?<p className="react-help">Accounts will appear after joining with the UCN.</p>:null}</div></Panel></div>;
}

export function GameplayWorkspace({ campaignId, workspace, partyWorkspace, saveSection }) {
  const gameplay=workspace.gameplay||{};const [view,setView]=useState('encounters');const [draft,setDraft]=useState({name:'',detail:'',reward:''});const [notes,setNotes]=useState(gameplay.sharedNotes||partyWorkspace?.sharedNotes||'');const [message,setMessage]=useState('');
  useEffect(()=>setNotes(gameplay.sharedNotes||partyWorkspace?.sharedNotes||''),[gameplay.sharedNotes,partyWorkspace?.sharedNotes]);
  const keys={encounters:'encounterTemplates',loot:'lootTables',guild:'guildContracts',professions:'professionAssignments'};const key=keys[view];const records=key?array(gameplay[key]):[];
  const singular={encounters:'encounter',loot:'loot table',professions:'profession assignment',guild:'guild contract'};
  const save=async next=>{const result=await saveSection('gameplay',next);setMessage(result?.ok?'Gameplay systems synchronized.':result?.error||'Gameplay system could not be saved.');};
  const add=()=>{if(!draft.name.trim())return setMessage('Enter a name.');save({...gameplay,[key]:[{...draft,id:uid(key),createdAt:new Date().toISOString()},...records]});setDraft({name:'',detail:'',reward:''});};
  const loadEncounter=record=>firebaseService.saveEncounter(campaignId,{status:'ready',round:1,turnIndex:0,combatants:[],enemies:[],name:record.name,notes:record.detail,templateId:record.id});
  return <Panel title="Gameplay Systems" eyebrow="Encounters, Loot, Professions, Party & Guild" action={<div className="react-segmented-actions">{['encounters','loot','professions','guild','party'].map(id=><button key={id} className={view===id?'active':''} onClick={()=>setView(id)}>{id}</button>)}</div>}>{view==='party'?<div><label>Shared Party Notes<textarea className="react-gm-notebook short" value={notes} onChange={event=>setNotes(event.target.value)}/></label><button className="primary" onClick={()=>save({...gameplay,sharedNotes:notes})}>Save Shared Notes</button></div>:<div className="react-gm-workspace-grid gameplay"><section><div className="react-form-grid"><label>Name<input value={draft.name} onChange={event=>setDraft(value=>({...value,name:event.target.value}))}/></label><label>Reward / Value<input value={draft.reward} onChange={event=>setDraft(value=>({...value,reward:event.target.value}))}/></label></div><label>Details<textarea rows="6" value={draft.detail} onChange={event=>setDraft(value=>({...value,detail:event.target.value}))}/></label><button className="primary" onClick={add}>Add {singular[view]}</button></section><section><div className="react-record-list">{records.map(record=><article key={record.id}><div className="react-record-heading"><h3>{record.name}</h3><small>{record.reward}</small></div><p>{record.detail||'No details recorded.'}</p><div className="react-action-row">{view==='encounters'?<button onClick={()=>loadEncounter(record)}>Load into Encounter Tracker</button>:null}<button className="danger" onClick={()=>save({...gameplay,[key]:records.filter(item=>item.id!==record.id)})}>Delete</button></div></article>)}{!records.length?<EmptyState title={`No ${view} records`}/>:null}</div></section></div>}<SectionStatus message={message}/></Panel>;
}

const WORLD_SCHEMAS={
  regions:[['name','Region Name'],['status','Status'],['resources','Resources'],['travelSafety','Travel Safety']],
  factions:[['name','Faction Name'],['status','Standing'],['score','Reputation Score'],['notes','Notes']],
  events:[['title','Event Title'],['type','Event Type'],['region','Region'],['status','Status']],
  settlements:[['name','Settlement Name'],['region','Region'],['population','Population'],['state','State']],
  merchants:[['name','Merchant Name'],['type','Type'],['region','Region'],['wealth','Wealth']],
  timeline:[['title','Event Title'],['era','Era'],['type','Type'],['region','Region']],
  npcs:[['name','NPC Name'],['personality','Personality'],['goals','Goals'],['faction','Faction']],
  changes:[['title','World Change'],['region','Region'],['effect','Consequence'],['status','Status']],
  knowledge:[['title','Lore / Discovery'],['level','Knowledge Level'],['region','Region'],['notes','GM Notes']],
  discoveries:[['name','Discovery'],['region','Region'],['type','Type'],['status','Visibility']]
};

function WorldCollectionEditor({ category, world, save }) {
  const schema=WORLD_SCHEMAS[category];const records=array(world[category]);const empty=Object.fromEntries(schema.map(([key])=>[key,'']));const [draft,setDraft]=useState(empty);
  useEffect(()=>setDraft(empty),[category]);
  const add=()=>{const name=draft.name||draft.title;if(!String(name||'').trim())return;save({...world,[category]:[{...draft,id:uid(category),createdAt:new Date().toISOString()},...records]});setDraft(empty);};
  return <div className="react-gm-workspace-grid world-editor"><section><div className="react-form-grid">{schema.map(([key,label])=><label key={key}>{label}<input type={key==='score'||key==='population'||key==='wealth'?'number':'text'} value={draft[key]} onChange={event=>setDraft(value=>({...value,[key]:event.target.value}))}/></label>)}</div><button className="primary" onClick={add}>Add {category.slice(0,-1)}</button></section><section><div className="react-record-list">{records.map(record=><article key={record.id}><div className="react-record-heading"><h3>{record.name||record.title}</h3><small>{record.status||record.type||record.state||record.region}</small></div><p>{record.notes||record.resources||record.personality||record.goals||record.era||''}</p><button className="danger" onClick={()=>save({...world,[category]:records.filter(item=>item.id!==record.id)})}>Delete</button></article>)}{!records.length?<EmptyState title={`No ${category}`}/>:null}</div></section></div>;
}

export function WorldWorkspace({ workspace, saveSection }) {
  const world=workspace.world||{};const [view,setView]=useState('state');const [message,setMessage]=useState('');
  const worldState=()=>({kingdomStatus:world.kingdomStatus||'',settlementStatus:world.settlementStatus||'',economyStatus:world.economyStatus||'',factionStatus:world.factionStatus||'',creatureActivity:world.creatureActivity||'',magicalActivity:world.magicalActivity||'',politicalTension:Number(world.politicalTension||0),corruptionLevel:Number(world.corruptionLevel||0),resourceAvailability:world.resourceAvailability||'',weather:world.weather||'',gmNotes:world.gmNotes||''});
  const [stateDraft,setStateDraft]=useState(worldState);
  useEffect(()=>setStateDraft(worldState()),[world.kingdomStatus,world.settlementStatus,world.economyStatus,world.factionStatus,world.creatureActivity,world.magicalActivity,world.politicalTension,world.corruptionLevel,world.resourceAvailability,world.weather,world.gmNotes]);
  const save=async next=>{const result=await saveSection('world',next);setMessage(result?.ok?'World systems synchronized.':result?.error||'World system could not be saved.');};
  return <Panel title="World Systems" eyebrow="Living Campaign World" action={<div className="react-world-tabs">{['state',...Object.keys(WORLD_SCHEMAS)].map(id=><button key={id} className={view===id?'active':''} onClick={()=>setView(id)}>{id}</button>)}</div>}>{view==='state'?<div className="react-gm-workspace-grid world-state"><section><div className="react-form-grid"><label>Kingdom Status<input value={stateDraft.kingdomStatus} onChange={event=>setStateDraft(value=>({...value,kingdomStatus:event.target.value}))}/></label><label>Settlement Status<input value={stateDraft.settlementStatus} onChange={event=>setStateDraft(value=>({...value,settlementStatus:event.target.value}))}/></label><label>Economy Status<input value={stateDraft.economyStatus} onChange={event=>setStateDraft(value=>({...value,economyStatus:event.target.value}))}/></label><label>Faction Status<input value={stateDraft.factionStatus} onChange={event=>setStateDraft(value=>({...value,factionStatus:event.target.value}))}/></label><label>Creature Activity<input value={stateDraft.creatureActivity} onChange={event=>setStateDraft(value=>({...value,creatureActivity:event.target.value}))}/></label><label>Magical Activity<input value={stateDraft.magicalActivity} onChange={event=>setStateDraft(value=>({...value,magicalActivity:event.target.value}))}/></label><label>Political Tension<input type="number" value={stateDraft.politicalTension} onChange={event=>setStateDraft(value=>({...value,politicalTension:Number(event.target.value||0)}))}/></label><label>Corruption Level<input type="number" value={stateDraft.corruptionLevel} onChange={event=>setStateDraft(value=>({...value,corruptionLevel:Number(event.target.value||0)}))}/></label><label>Resources<input value={stateDraft.resourceAvailability} onChange={event=>setStateDraft(value=>({...value,resourceAvailability:event.target.value}))}/></label><label>Weather<input value={stateDraft.weather} onChange={event=>setStateDraft(value=>({...value,weather:event.target.value}))}/></label></div><button className="primary" onClick={()=>save({...world,...stateDraft})}>Apply World State</button></section><section><label>World Control Notes<textarea rows="10" value={stateDraft.gmNotes} onChange={event=>setStateDraft(value=>({...value,gmNotes:event.target.value}))}/></label></section></div>:<WorldCollectionEditor category={view} world={world} save={save}/>}<SectionStatus message={message}/></Panel>;
}
